const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)], esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageKey='vuontoan4-v1';
let state={name:'Bạn nhỏ',start:'',voice:'',voiceConfirmedURI:'',rate:.9,audio:true,completed:[],read:[],results:[]},storageOK=true;
try{const s=JSON.parse(localStorage.getItem('vuontoan4-v1')||'null');if(s&&Array.isArray(s.results)&&Array.isArray(s.completed)&&Array.isArray(s.read))state={...state,...s}}catch(e){storageOK=false}
function save(){try{if(typeof MIALearning!=='undefined'&&typeof LESSONS!=='undefined'){let context=MIALearning.context(state,LESSONS,DAYS),topics=MIALearning.topics(state,correct),learningPlan=MIAAdvisorCore.analyze(state,LESSONS,DAYS,correct);state.learning=MIALearning.clean(state.learning);state.learning.summary={schoolLesson:context.previous?.lesson||null,schoolTitle:context.previous?LESSONS[context.previous.lesson-1]?.title:null,schoolDay:context.previous?.day||null,schoolDate:context.previous?.date||null,feeling:context.previous?.feeling||null,planDate:learningPlan.date,tasks:learningPlan.tasks.map(t=>({title:t.title,done:t.done})),topics:topics.map(t=>({key:t.key,n:t.n,good:t.good,level:t.level,title:topicLesson(t.key)?.title||t.key})).slice(0,50)}}localStorage.setItem(storageKey,JSON.stringify(state));if(typeof MIAOnline!=='undefined')MIAOnline.queueProgress(state)}catch(e){storageOK=false;toast('Trình duyệt chưa lưu được. Hãy xuất bản sao tiến độ.')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
const KINDS={daily:'Cuối ngày',week:'Cuối tuần',month:'Cuối tháng',quarter:'Cuối quý',mid:'Giữa học kì',term:'Cuối học kì'};
KINDS.custom='Bài tự chọn của con';
let currentDay=1,currentTab='theory',exam=null,practice=[],chatQuestion=null,messages=[],voices=[],recognition=null,speechRequest=0,previewedVoiceURI='',teacherAudio=null;
const teacher=`<svg class="teacher-art" viewBox="0 0 240 255" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Cô Mi A tóc nâu, áo xanh, đang cầm sách và mỉm cười"><circle cx="120" cy="126" r="101" fill="#f5f8e8"/><circle cx="202" cy="68" r="12" fill="#f5cd69"/><path d="M31 149l5-12 5 12 12 5-12 5-5 12-5-12-12-5z" fill="#91b58c"/><path d="M70 109c-10-65 18-88 51-87 39 1 61 28 50 91l-5 43H72z" fill="#614139"/><path d="M73 96c-1-44 15-60 48-60s53 22 48 60l-7 37c-11 31-68 31-80-1z" fill="#f5c5a3"/><path d="M73 75c25-1 42-17 48-30 12 15 27 22 49 25-7-37-28-45-50-44-24-1-44 16-47 49" fill="#614139"/><path d="M101 144v18h42v-19" fill="#efb790"/><path d="M65 175c13-18 31-19 36-20l21 19 20-19c18 2 37 8 42 29l12 71H44z" fill="#4f8d71"/><path d="M101 155l21 19-14 17-17-30m51-6l-20 19 15 17 15-30" fill="#f4f5df"/><circle cx="100" cy="98" r="3.5" fill="#513b35"/><circle cx="144" cy="98" r="3.5" fill="#513b35"/><path d="M112 117q10 11 20 0" fill="none" stroke="#a75850" stroke-width="3" stroke-linecap="round"/><ellipse cx="89" cy="111" rx="9" ry="4" fill="#efa3a0" opacity=".65"/><ellipse cx="154" cy="111" rx="9" ry="4" fill="#efa3a0" opacity=".65"/><path d="M59 191l29 28 46-8" fill="none" stroke="#f5c5a3" stroke-width="18" stroke-linecap="round"/><path d="M126 200l57-11 10 57-58 9z" fill="#f6cd71"/><path d="M134 207l41-8m-39 16l40-8" stroke="#d6a64c" stroke-width="2"/><path d="M181 189l19-36" stroke="#f5c5a3" stroke-width="15" stroke-linecap="round"/><circle cx="202" cy="144" r="11" fill="#f5c5a3"/><path d="M199 142v-15" stroke="#f5c5a3" stroke-width="6" stroke-linecap="round"/><text x="25" y="55" font-size="24" fill="#8da77c">✦</text></svg>`;
function nextDay(){return DAYS.find(d=>!state.completed.includes(d.id))?.id||175}
function dateFor(id){if(!state.start)return '';let d=new Date(state.start+'T12:00:00'),count=0;if(Number.isNaN(d.getTime()))return '';while(d.getDay()===0||d.getDay()===6)d.setDate(d.getDate()+1);while(count<id-1){d.setDate(d.getDate()+1);if(d.getDay()!==0&&d.getDay()!==6)count++}return d.toLocaleDateString('vi-VN')}
function dayLink(id){let d=DAYS[id-1],l=LESSONS[d.lesson-1];return `<div class="lesson-row"><span class="number">${state.completed.includes(id)?'✓':id}</span><div><h3><a class="lesson-title-link" href="#lesson/${id}">${esc(l.title)}</a></h3><p>Bài ${l.id} · Buổi ${d.session}/${d.total} · Tập ${l.book}, tr. ${d.start}${d.end!==d.start?'–'+d.end:''}${dateFor(id)?' · '+dateFor(id):''}</p></div><a class="arrow" href="#lesson/${id}" aria-label="Vào học ngày ${id}: ${esc(l.title)}"><span>Vào học</span> <b aria-hidden="true">→</b></a></div>`}
function intro(eyebrow,title,text){return `<div class="intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${text}</p></div><span class="badge">✦ KẾT NỐI TRI THỨC</span></div>`}
function route(){let parts=location.hash.slice(1).split('/'),view=parts[0]||'home';if(view==='settings'){location.replace('#parents');return}document.body.classList.toggle('parent-report-view',view==='parents');if(window.MIAAccess&&!MIAAccess.check(view))return;if(exam&&!exam.submitted&&view!=='exam'){if(!confirm('Em đang làm bài kiểm tra. Rời trang sẽ bỏ phần trả lời chưa nộp. Em muốn rời trang?')){location.hash='exam';return}exam=null}stopSpeech();if(typeof ExamTeacher!=='undefined')ExamTeacher.stop();if(typeof MIAOnline!=='undefined')MIAOnline.beforeRoute(view);$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.nav===view||(view==='lesson'&&a.dataset.nav==='roadmap')||(view==='exam'&&a.dataset.nav==='exams')));$('#profileName').textContent=state.name+' · Lớp 4';$('#crumb').textContent=({home:'Hôm nay học gì?',roadmap:'Học theo sách giáo khoa',lesson:'Học cùng cô Mi A',exams:'Góc kiểm tra',online:'Thi online cùng MIA',exam:'Bài kiểm tra',progress:'Thành quả',honors:'Vườn sao chăm học',parents:'Báo cáo học tập cho phụ huynh',friends:'Bạn bè và nhóm học Toán',advisor:'Cố vấn học tập MIA',library:'Thư viện',settings:'Dành cho phụ huynh'})[view]||'Góc học tập';let app=$('#app');if(view==='home')app.innerHTML=home();else if(view==='roadmap')app.innerHTML=roadmap();else if(view==='lesson'){currentDay=Math.max(1,Math.min(175,parseInt(parts[1])||1));currentTab=['book','practice','daily'].includes(parts[2])?parts[2]:'theory';practice=[];if(currentTab==='practice')practice=makePractice(currentDay);app.innerHTML=lesson();}else if(view==='online'){app.innerHTML=MIAOnline.render();MIAOnline.mount()}else if(view==='exams')app.innerHTML=exams();else if(view==='exam'){if(exam)renderExam();else app.innerHTML=exams()}else if(view==='friends'){app.innerHTML=MIAFriends.page();MIAFriends.mount()}else if(view==='advisor'){app.innerHTML=MIAAdvisor.page();MIAAdvisor.mount()}else if(view==='honors'||view==='parents'){app.innerHTML=MIARewards.page(view);MIARewards.load(view)}else if(view==='progress')app.innerHTML=progress();else if(view==='library')app.innerHTML=library();else if(view==='settings'){app.innerHTML=settings();fillVoices()}else{app.innerHTML=home()}window.scrollTo(0,0);if(view==='lesson'&&typeof MIALessonCoach!=='undefined')MIALessonCoach.mount()}
function home(){let basePlan=MIALearning.plan(state,LESSONS,DAYS,correct),advice=MIAAdvisorCore.analyze(state,LESSONS,DAYS,correct),learningPlan={...basePlan,tasks:advice.tasks,minutes:advice.minutes,done:advice.tasks.filter(t=>t.done).length},n=learningPlan.day,d=DAYS[n-1],l=LESSONS[d.lesson-1],week=Math.ceil(n/5),avg=state.results.length?(state.results.reduce((s,r)=>s+r.score,0)/state.results.length).toFixed(1):'—';if(!learningPlan.current)return intro('MỖI NGÀY MỘT KHÁM PHÁ',`Chào ${esc(state.name)}, cô Mi A chờ con đây! 🌷`,'Mình chọn đúng bài trên lớp trước, rồi cô sắp xếp việc hôm nay nhé.')+checkinCard(learningPlan)+MIAAdvisor.summary()+`<section class="card mia-welcome-study">${teacher}<div><h2>Mình học theo nhịp của con</h2><p>Cô sẽ giải thích chậm, viết ví dụ từng bước và xem bài con làm để biết chỗ cần luyện thêm.</p><p>Hôm nay chỉ cần những việc nhỏ vừa sức: nghe giảng, xem sách, luyện ba câu và thử bài kiểm tra ngắn.</p></div></section>`;return intro('MỖI NGÀY MỘT KHÁM PHÁ',`Chào ${esc(state.name)}, cùng học Toán nhé! 🌿`,'Một bài học nhỏ hôm nay, một bước tự tin ngày mai.')+checkinCard(learningPlan)+MIAAdvisor.summary()+dailyPlanCard(learningPlan)+`<section class="hero"><div><span class="tag">TUẦN ${week} · NGÀY HỌC ${n}</span><h2><a class="lesson-title-link" href="#lesson/${n}">${esc(l.title)}</a></h2><p>Cô Mi A sẽ cùng em khám phá, làm thử rồi tự tin chinh phục bài học này.</p><div class="btn-row"><a class="btn" href="#lesson/${n}">Vào học cùng cô &nbsp; →</a><a class="btn secondary" href="#roadmap">Học theo sách giáo khoa</a></div></div><div class="mia-hero-scene" aria-hidden="true"><span class="mia-orbit orbit-one">✦</span><span class="mia-orbit orbit-two">+</span><span class="mia-orbit orbit-three">÷</span><div class="mia-hero-moon"></div><div class="mia-hero-cloud cloud-one"></div><div class="mia-hero-cloud cloud-two"></div><div class="mia-hero-platform"></div>${teacher}<div class="mia-hero-book"><span>1 2 3</span><b>TOÁN 4</b><small>Mỗi ngày một khám phá</small></div><span class="mia-hero-buddy">🌷</span></div></section><section class="stats"><div class="stat"><span class="stat-icon">📖</span><div><b>${state.completed.length}<small>ngày học đã hoàn thành / 175</small></b></div></div><div class="stat"><span class="stat-icon">✎</span><div><b>${state.results.length}<small>bài kiểm tra đã nộp</small></b></div></div><div class="stat"><span class="stat-icon">☆</span><div><b>${avg}<small>điểm trung bình / 10</small></b></div></div></section><div class="columns"><section><div class="section-head"><h2>Các buổi của bài đang học trên lớp</h2><a href="#roadmap">Tất cả bài học →</a></div><div class="card">${DAYS.filter(x=>x.lesson===l.id).map(x=>dayLink(x.id)).join('')}</div><div class="note">73 bài theo mục lục hai PDF gốc. Lịch 175 ngày / 35 tuần là gợi ý phân bổ, có thể chọn bất kì bài nào theo tiến độ trên lớp.</div></section><section><div class="section-head"><h2>Tuần này của em</h2><span class="tag">Tuần ${week}</span></div><div class="card"><div class="meta">Mỗi ô là một ngày đến lớp</div><div class="mini-week">${DAYS.slice((week-1)*5,week*5).map(x=>`<button class="${state.completed.includes(x.id)?'done':''}" onclick="location.hash='lesson/${x.id}'" aria-label="Ngày ${x.id}">${state.completed.includes(x.id)?'✓':x.id}</button>`).join('')}</div><div class="progress-track"><span style="width:${state.completed.filter(x=>x>=(week-1)*5+1&&x<=week*5).length*20}%"></span></div><p class="meta" style="margin:12px 0">Một chút chăm chỉ, thật nhiều tiến bộ.</p><button class="btn secondary" onclick="openExamPicker('week',${week*5})">✎ Kiểm tra cuối tuần</button></div><div class="card tip"><h3>💡 Cô Mi A nhắn nhỏ</h3><p>Chưa làm đúng cũng không sao. Mình đọc lại đề, thử từng bước, rồi cùng tìm cách nhé!</p></div></section></div>`}
function roadmap(){return intro('SÁCH GIÁO KHOA TOÁN 4','Học theo sách giáo khoa','Chọn đúng bài em đang học trên lớp; xem lời giảng, ví dụ và trang sách gốc.')+`<div class="top-controls"><input type="search" id="lessonSearch" aria-label="Tìm bài học" placeholder="Tìm tên bài, ví dụ: phân số, góc..." oninput="filterRoadmap()"><select id="termFilter" aria-label="Lọc học kì" onchange="filterRoadmap()"><option value="all">Cả năm học</option><option value="1">Học kì I · Ngày 1–90</option><option value="2">Học kì II · Ngày 91–175</option></select></div><p class="legend">✓ Đã hoàn thành · Lịch gợi ý 5 buổi/tuần; ngày nghỉ lễ chưa được trừ. Trang sách gốc được giữ đầy đủ.</p><div id="weeks" class="week-grid">${weekCards('', 'all')}</div>`}
function weekCards(search,term){let html='';for(let w=1;w<=35;w++){let ds=DAYS.slice((w-1)*5,w*5).filter(d=>(term==='all'||(term==='1'?d.id<=90:d.id>90))&&normal(LESSONS[d.lesson-1].title+' '+d.lesson).includes(normal(search)));if(ds.length)html+=`<section class="card week-card"><div class="section-head"><h3>Tuần ${w}</h3><span class="tag">${w<=18?'Học kì I':'Học kì II'}</span></div>${ds.map(d=>dayLink(d.id)).join('')}<button style="margin-top:18px;font-size:12px" onclick="openExamPicker('week',${w*5})">Kiểm tra tuần ${w} →</button></section>`}return html||'<div class="empty">Không tìm thấy bài phù hợp.</div>'}
function filterRoadmap(){$('#weeks').innerHTML=weekCards($('#lessonSearch').value,$('#termFilter').value)}
function lesson(){let d=DAYS[currentDay-1],l=LESSONS[d.lesson-1];return intro(`NGÀY ${d.id} · TUẦN ${Math.ceil(d.id/5)} · BUỔI ${d.session}/${d.total}`,`Bài ${l.id}. ${esc(l.title)}`,`Tập ${l.book} · Bài gốc trang ${l.page}–${l.end} · Hôm nay xem trang ${d.start}–${d.end}${dateFor(d.id)?' · '+dateFor(d.id):''}`)+`<div class="btn-row no-print"><button class="btn secondary" onclick="goDay(-1)" ${d.id===1?'disabled':''}>← Ngày trước</button><button class="btn secondary" onclick="goDay(1)" ${d.id===175?'disabled':''}>Ngày tiếp →</button><span class="tag">${state.completed.includes(d.id)?'✓ Đã hoàn thành':'🌱 Đang khám phá'}</span></div><div class="tabs" role="group" aria-label="Các phần bài học">${[['theory','01 · Cô giảng bài'],['book','02 · Sách giáo khoa'],['practice','03 · Cùng luyện tập'],['daily','04 · Kiểm tra ngày']].map(([k,t])=>`<button class="${currentTab===k?'active':''}" onclick="setTab('${k}')">${t}</button>`).join('')}</div>${MIALessonCoach.markup()}<div class="lesson-layout"><div id="lessonContent">${lessonContent()}</div><aside class="sticky"><div class="card"><span class="eyebrow">MỘT BUỔI HỌC NHẸ NHÀNG</span><ul class="checklist"><li><span>1</span> Nghe và đọc lời cô giảng</li><li><span>2</span> Xem từng trang sách gốc</li><li><span>3</span> Thử bài luyện và hỏi cô</li><li><span>4</span> Làm kiểm tra cuối ngày</li></ul><button class="btn" onclick="toggleChat(true)">💬 Em muốn hỏi cô</button></div><div class="card tip"><h3>🌷 Cô Mi A nhắc em</h3><p>Mỗi buổi khoảng 30–35 phút. Đứng lên vươn vai khi thấy mỏi nhé!</p></div><p class="meta">Lời giảng và câu hỏi tương tác là nội dung bổ trợ. Các trang sách gốc là căn cứ đối chiếu của bài.</p></aside></div>`}
function goDay(delta){location.hash='lesson/'+Math.max(1,Math.min(175,currentDay+delta))}
function setTab(t){if(window.MIAAccess&&!MIAAccess.require())return;currentTab=t;stopSpeech();if(t==='practice')practice=makePractice(currentDay);$('#app').innerHTML=lesson();if(state.audio)MIALessonCoach.read(t==='theory'?'intro':t)}
function lessonContent(){let d=DAYS[currentDay-1],l=LESSONS[d.lesson-1],g=G[l.key];if(currentTab==='theory')return studioMarkup(l,d)+MIAVisuals.markup(l,d)+MIAAdvisor.lessonPanel(currentDay)+`<details class="card mia-summary-notes"><summary>Ghi nhớ nhanh và ví dụ tham khảo</summary><section><div class="section-head"><h2>Chậm một chút, hiểu thật chắc</h2><span>🌷</span></div><p class="meta">Buổi ${d.session}: ${d.session===1?'Khám phá kiến thức':d.session===d.total?'Củng cố và vận dụng':'Luyện cách làm'} · Lời giảng bổ trợ</p><h3>Điều em cần nhớ</h3><p style="color:var(--ink)">${esc(g.rule)}</p><ol class="steps">${g.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="btn-row"><button class="btn" onclick="readShortGuide()">▶ Nghe bản tóm tắt</button><button onclick="stopSpeech()">■ Dừng đọc</button></div><div id="readStatus" class="read-status">Bài giảng dùng bản đọc giọng nữ Hoài My kèm sẵn, không lấy giọng mặc định của Chrome.</div></section><section class="card"><h2>💡 Cô làm mẫu, em quan sát</h2><div class="example">${esc(g.example)}</div><div class="callout"><b>Mẹo tránh nhầm:</b> ${esc(g.mistake)}</div><p class="meta" style="margin-top:16px">Lấy giấy nháp, tự làm lại ví dụ rồi nói với cô cách em nghĩ.</p><div class="btn-row"><button onclick="ask('Cô hỏi em nhé');toggleChat(true)">Thử trả lời cô</button><button class="btn" onclick="markRead();setTab('book')">Em đã hiểu, xem sách →</button></div></section></details>`;
 if(currentTab==='book'){let pages=[];for(let p=d.start;p<=d.end;p++)pages.push(p);return `<div class="card"><h2>Trang sách của buổi hôm nay</h2><p class="meta">Ảnh nguyên trang từ PDF bạn đã gửi, không biên tập lại nội dung. Hãy đọc hướng dẫn và làm các bài trong sách vào vở.</p><a href="tai-lieu/sgk-tap-${l.book}.pdf#page=${l.page+1}" target="_blank" rel="noopener">Mở PDF đầy đủ · tập ${l.book} ↗</a>${pages.map(p=>`<img class="page-img" src="assets/b${l.book}-${p}.jpg" alt="Sách Toán 4 tập ${l.book}, trang ${p}" loading="lazy"><div class="page-label">Trang ${p} · Tập ${l.book}</div>`).join('')}<details><summary>Xem toàn bộ bài ${l.id}: trang ${l.page}–${l.end}</summary>${Array.from({length:l.end-l.page+1},(_,i)=>l.page+i).map(p=>`<img class="page-img" src="assets/b${l.book}-${p}.jpg" alt="Toàn bài, trang ${p}" loading="lazy">`).join('')}</details><div class="btn-row" style="margin-top:24px"><button class="btn" onclick="markRead();setTab('practice')">Em đã học trang sách, luyện tập →</button></div></div>`}
 if(currentTab==='practice'){if(!practice.length)practice=makePractice(currentDay);return `<div class="card"><h2>Em thử nhé! ✏️</h2><p>Làm thử thoải mái. Cô sẽ giải thích từng câu, không tính vào điểm kiểm tra.</p></div>${practice.map((q,i)=>renderQuestion(q,i,'p')).join('')}<div class="btn-row"><button class="btn" onclick="checkPractice()">Cô xem giúp em</button><button onclick="setTab('practice')">Đổi câu luyện</button><button class="btn secondary" onclick="setTab('daily')">Đến kiểm tra cuối ngày →</button></div><div id="practiceAdvice"></div>`}
 return `<div class="card"><span class="eyebrow">CHỐT LẠI ĐIỀU EM ĐÃ HỌC</span><h2>Kiểm tra cuối ngày ${currentDay}</h2><p>5 câu · Khoảng 10 phút · Được xem lời giải sau khi nộp bài.</p><div class="note">Em hãy học phần cô giảng và trang sách trước khi bắt đầu. Bài kiểm tra là nội dung bổ trợ, có ghi nguồn từng câu.</div><div class="btn-row" style="margin-top:22px"><button class="btn" onclick="startExam('daily',${currentDay})" ${state.read.includes(currentDay)?'':'disabled'}>Bắt đầu kiểm tra →</button></div>${!state.read.includes(currentDay)?'<p class="meta" style="margin-top:14px">Hãy trở về “Cô giảng bài”, chọn “Em đã hiểu”, rồi học trang sách.</p>':''}</div>`}
function markRead(){if(window.MIAAccess&&!MIAAccess.require())return;learningRecord(currentTab==='book'?'book-read':'theory-read',currentDay);if(!state.read.includes(currentDay)){state.read.push(currentDay);save()}}
function renderQuestion(q,i,prefix,answer,graded=false){let ok=graded&&correct(answer,q.answer);return `<section class="question ${graded?(ok?'result-good':'result-bad'):''}" id="${prefix}q${i}"><span class="eyebrow">CÂU ${i+1}</span><h3>${esc(q.q)}</h3>${q.options?`<div class="options">${q.options.map((o,j)=>`<label class="option"><input type="radio" name="${prefix}${i}" value="${esc(o)}" ${answer===o?'checked':''} ${graded?'disabled':''}>${esc(o)}</label>`).join('')}</div>`:`<label class="sr" for="${prefix}${i}">Câu trả lời ${i+1}</label><input id="${prefix}${i}" name="${prefix}${i}" value="${esc(answer||'')}" placeholder="Nhập số, phân số dạng 2/3 hoặc câu trả lời" autocomplete="off" ${graded?'disabled':''}>`}<p class="source">Nguồn: ${esc(q.source)}</p>${graded?`<div class="feedback"><b>${ok?'✓ Em làm đúng rồi!':'Cùng xem lại nhé.'}</b>${!ok?`<br>Em trả lời: ${esc(answer||'(chưa trả lời)')}<br>Đáp án: <b>${esc(q.answer)}</b>`:''}<br>${esc(q.why)}</div>`:''}</section>`}
function readAnswer(prefix,i){let radio=document.querySelector(`input[type=radio][name="${prefix}${i}"]:checked`);return radio?radio.value:(document.getElementById(prefix+i)?.value||'')}
function makePractice(day){let key=LESSONS[DAYS[day-1].lesson-1].key,items=[],seen=new Set();for(let i=0;items.length<3&&i<200;i++){let q=question(key,Math.floor(Math.random()*100000));if(!seen.has(q.q)){seen.add(q.q);items.push(q)}}return items}
function checkPractice(){if(window.MIAAccess&&!MIAAccess.require())return;let answers=practice.map((_,i)=>readAnswer('p',i));if(answers.every(x=>!String(x).trim())){toast('Em thử làm ít nhất một câu rồi nhờ cô xem nhé. Nếu chưa hiểu, mình nghe lại phần cô giảng.');return}if(!practice.every(q=>q.checked)){learningRecord('practice',currentDay,{answers:practice.map((q,i)=>({key:q.key,prompt:q.q,input:answers[i],answer:String(q.answer),explanation:q.why||'',attempted:!!String(answers[i]).trim(),correct:correct(answers[i],q.answer)}))});practice.forEach(q=>q.checked=true);}if(window.MIARewards&&practice.some((q,i)=>correct(answers[i],q.answer)))MIARewards.celebrate('Bravo! Em đã giải đúng. Cô tự hào về sự cố gắng của em!');practice.forEach((q,i)=>{$('#pq'+i).outerHTML=renderQuestion(q,i,'p',answers[i],true)});if($('#practiceAdvice'))$('#practiceAdvice').innerHTML=MIAAdvisor.summary();toast('Cô đã giải thích dưới từng câu và gợi ý bước tiếp theo cho em.')}
function exams(){let day=nextDay();return MIASelfTests.picker()+intro('THỬ SỨC ĐỂ HIỂU MÌNH HƠN','Góc kiểm tra của em','Học chắc từng chặng, rồi cùng nhìn lại những điều đã biết.')+`<div class="note">Phạm vi theo lịch gợi ý. Em chọn mốc cuối chặng trước khi tạo đề. Câu hỏi tự chấm gồm câu trích có đối chiếu và câu bổ sung; đề gốc nằm trong Thư viện.</div><div class="exam-grid" style="margin-top:24px">${Object.entries(KINDS).filter(([k])=>k!=='custom').map(([k,t],i)=>`<div class="card exam-card"><span>${['🌤','🌿','🌻','🌳','📚','🏅'][i]}</span><h3 style="margin-top:12px">${t}</h3><p>${{daily:'5 câu · kiến thức của ngày',week:'10 câu · 5 ngày học gần nhất',month:'15 câu · chặng 20 ngày học',quarter:'20 câu · chặng 60 ngày học',mid:'20 câu · từ đầu học kì đến mốc chọn',term:'25 câu · toàn bộ học kì đã chọn'}[k]}</p><button class="btn secondary" onclick="openExamPicker('${k}',${day})">Chọn chặng kiểm tra →</button></div>`).join('')}</div><div id="examPicker" style="margin-top:25px"></div>`}
function checkpointLabel(day){let d=DAYS[day-1],l=LESSONS[d.lesson-1];return 'Ngày '+day+' · Bài '+l.id+'. '+l.title+' · Tập '+l.book+', trang '+d.start+'–'+d.end+' · '+(day<=90?'Học kì I':'Học kì II')}
function openExamPicker(kind,end){if(window.MIAAccess&&!MIAAccess.require())return;if(!$('#examPicker')){$('#app').innerHTML=exams();$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.nav==='exams'))}let endpoints=kind==='daily'?DAYS.map(d=>d.id):kind==='week'?Array.from({length:35},(_,i)=>(i+1)*5):kind==='month'?[20,40,60,80,90,110,130,150,170,175]:kind==='quarter'?[60,90,150,175]:kind==='mid'?[45,135]:[90,175];let selected=endpoints.find(e=>e>=end)||endpoints.at(-1);$('#examPicker').innerHTML=`<div class="card"><h2>${KINDS[kind]} · Chọn mốc học</h2><label class="field">Chặng kiểm tra<select id="examEnd">${endpoints.map(e=>`<option value="${e}" ${e===selected?'selected':''}>${kind==='week'?'Tuần '+e/5+' · ':''}Đến ${esc(checkpointLabel(e))}</option>`).join('')}</select></label><p class="meta">Tháng và quý quy ước theo ngày học; chặng cuối học kì có thể ngắn hơn. Mốc giữa kì là gợi ý, chưa phải lịch thi của trường.</p><button class="btn" onclick="startExam('${kind}',Number($('#examEnd').value))">Tạo đề và bắt đầu →</button></div>`;$('#examPicker').scrollIntoView({behavior:'smooth'})}
function startExam(kind,day){if(window.MIAAccess&&!MIAAccess.require())return;if(kind==='custom')return MIASelfTests.start(exam?.customSpec);if(typeof ExamTeacher!=='undefined')ExamTeacher.unlock();if(exam&&!exam.submitted&&!confirm('Em muốn bỏ bài đang làm và tạo đề mới?'))return;exam={...makeExam(day,kind),answers:[],submitted:false,began:Date.now()};location.hash='exam';renderExam()}
function renderExam(){if(!exam)return;$('#app').innerHTML=intro('BÌNH TĨNH, EM LÀM ĐƯỢC',`${KINDS[exam.kind]} · ${exam.kind==='custom'?esc(exam.titles?.join(' · ')||'Bài tự chọn'):'Ngày '+exam.start+'–'+exam.end}`,`${exam.qs.length} câu · Mỗi câu bằng điểm nhau · Không giới hạn thời gian`)+`<div class="card no-print"><div class="btn-row"><button onclick="window.print()">In đề / Lưu PDF</button><span class="meta">Viết phân số bằng dấu /, ví dụ 2/3. Phân số bằng nhau đều được chấp nhận.</span></div></div><form id="examForm">${exam.qs.map((q,i)=>`<section class="mia-local-question">${!exam.submitted?`<div class="mia-local-coach-controls"><button type="button" onclick="readExamQuestion(${i})">🔊 Cô đọc câu ${i+1}</button><button type="button" onclick="hintExamQuestion(${i})">🌱 Nhắc kiến thức</button></div><p id="localHint${i}" class="mia-local-hint" hidden></p>`:''}${renderQuestion(q,i,'e',exam.answers[i],exam.submitted)}</section>`).join('')}${!exam.submitted?'<div class="btn-row"><button class="btn" type="submit">Nộp bài để cô chấm →</button></div>':''}</form>`;if(!exam.submitted)$('#examForm').onsubmit=e=>{e.preventDefault();submitExam()};if(exam.submitted)showScore();else if(!exam.audioStarted){exam.audioStarted=true;let active=exam;setTimeout(()=>{if(exam===active&&location.hash==='#exam')readExamQuestion(0)},300)}}
function readExamQuestion(index){if(window.MIAAccess&&!MIAAccess.require())return;if(!exam?.qs[index])return;if(typeof ExamTeacher!=='undefined'){ExamTeacher.setEnabled(true);ExamTeacher.speak('Câu '+(index+1)+'. '+exam.qs[index].q)}}
function hintExamQuestion(index){if(window.MIAAccess&&!MIAAccess.require())return;let q=exam?.qs[index],g=q&&G[q.key];if(!g)return;let el=document.querySelector('#localHint'+index);if(el){el.hidden=false;el.textContent='Cô nhắc em: '+g.rule}if(typeof ExamTeacher!=='undefined'){ExamTeacher.setEnabled(true);ExamTeacher.speak(g.rule,'hint:'+q.key)}}
function submitExam(){if(window.MIAAccess&&!MIAAccess.require())return;if(!exam||exam.submitted)return;if(typeof ExamTeacher!=='undefined')ExamTeacher.stop();exam.answers=exam.qs.map((_,i)=>readAnswer('e',i));let empty=exam.answers.filter(x=>!String(x).trim()).length;if(empty&&!confirm(`Em còn ${empty} câu chưa trả lời. Vẫn nộp bài chứ?`))return;exam.submitted=true;let good=exam.qs.filter((q,i)=>correct(exam.answers[i],q.answer)).length;exam.score=Math.round(good/exam.qs.length*100)/10;exam.good=good;let record={date:new Date().toISOString(),kind:exam.kind,start:exam.start,end:exam.end,score:exam.score,good,total:exam.qs.length,minutes:Math.round((Date.now()-exam.began)/6000)/10,questions:exam.qs.map((q,i)=>({...q,input:exam.answers[i]})),...(exam.customSpec?{customSpec:exam.customSpec,titles:exam.titles}:{})};state.results.push(record);if(exam.kind==='daily'&&!state.completed.includes(exam.end))state.completed.push(exam.end);save();renderExam();if(good>0)window.MIARewards?.celebrate("Em đã làm đúng "+good+" câu! Mình cùng xem lời giải để giỏi hơn nhé!");window.scrollTo(0,0)}
function showScore(){let box=document.createElement('section');box.className='card';box.innerHTML=`<div class="eyebrow">${exam.score>=8?'MỘT BÔNG HOA CHO SỰ CỐ GẮNG!':'MỖI LẦN THỬ LÀ MỘT LẦN TIẾN BỘ'}</div><div class="score">${exam.score}<span style="font-size:20px;color:var(--muted)"> / 10</span></div><p>Đúng ${exam.good}/${exam.qs.length} câu. ${exam.score>=8?'Em đã nắm bài tốt. Hãy kể lại cách làm cho người thân nhé!':'Mình xem lời giải dưới từng câu và học lại phần còn nhầm nhé.'}</p><div class="btn-row"><a class="btn" href="#lesson/${exam.end}">Học lại bài liên quan</a><button onclick="startExam('${exam.kind}',${exam.end})">Làm đề khác</button><a href="#progress">Xem thành quả →</a></div>`;$('#examForm').before(box)}
function progress(){let rs=state.results;return knowledgeCard()+intro('MỖI NỖ LỰC ĐỀU ĐÁNG NHỚ','Khu vườn thành quả','Điểm số giúp em biết chỗ cần luyện. Cố gắng của em mới là điều cô trân trọng.')+`<div class="card"><h2>🌱 ${state.completed.length} / 175 ngày đã hoàn thành</h2><div class="progress-track"><span style="width:${state.completed.length/175*100}%"></span></div><p class="meta" style="margin:12px 0 0">Hoàn thành ngày khi đã nộp kiểm tra cuối ngày, không phụ thuộc điểm số. Điểm thấp được khuyến khích học lại.</p></div>${!rs.length?'<div class="card empty"><span>🌼</span><h2>Khu vườn đang chờ bông hoa đầu tiên</h2><p>Vào bài học, làm một bài kiểm tra và quay lại đây nhé!</p><a class="btn" href="#home">Cùng bắt đầu →</a></div>':`<div class="card"><h2>Nhật kí kiểm tra</h2><div class="table-wrap"><table><thead><tr><th>Ngày làm</th><th>Bài kiểm tra</th><th>Phạm vi</th><th>Điểm</th><th></th></tr></thead><tbody>${rs.map((r,i)=>`<tr><td>${new Date(r.date).toLocaleDateString('vi-VN')}</td><td>${KINDS[r.kind]}</td><td>${r.start}–${r.end}</td><td><b>${r.score}/10</b></td><td><button onclick="reviewResult(${i})">Xem lại</button></td></tr>`).reverse().join('')}</tbody></table></div></div>`}<div id="reviewResult"></div><div class="btn-row"><button class="btn secondary" onclick="exportProgress()">↓ Sao lưu tiến độ</button><button onclick="exportCSV()">↓ Xuất bảng điểm CSV</button></div>`}
function reviewResult(i){if(window.MIAAccess&&!MIAAccess.require())return;let r=state.results[i];$('#reviewResult').innerHTML=`<div class="card"><h2>Lời giải · ${KINDS[r.kind]} · ${r.score}/10</h2><p class="meta">Ngày học ${r.start}–${r.end}</p></div>`+r.questions.map((q,j)=>renderQuestion(q,j,'r',q.input,true)).join('');$('#reviewResult').scrollIntoView({behavior:'smooth'})}
function library(){return intro('NGUỒN HỌC LIỆU','Thư viện của gia đình','Sách gốc làm chương trình chính. Giáo án và đề KNTT được chọn làm nguồn tham khảo.')+`<div class="card"><h2>📚 Hai tập sách giáo khoa gốc</h2><p class="meta">Sách Toán 4 · Kết nối tri thức với cuộc sống · Tái bản lần thứ ba (theo bìa PDF).</p><div class="btn-row"><a class="btn" href="tai-lieu/sgk-tap-1.pdf" target="_blank" rel="noopener">Mở tập 1 ↗</a><a class="btn secondary" href="tai-lieu/sgk-tap-2.pdf" target="_blank" rel="noopener">Mở tập 2 ↗</a></div></div><div class="note">Bản này tích hợp ${SOURCES.length} tài liệu Word KNTT và đề chung phù hợp. Tài liệu Cánh Diều, Chân trời sáng tạo và các tài liệu khác chưa được nhập. Bài tự chấm có nguồn tại từng câu; không phải mọi đề gốc đều đã chuyển thành câu tương tác. Bản xem văn bản có thể thiếu công thức/hình: hãy tải Word gốc để dùng đầy đủ.</div><div class="top-controls"><input type="search" id="sourceSearch" aria-label="Tìm tài liệu" placeholder="Tìm tài liệu, ví dụ: tuần 1, giữa, HK2..." oninput="filterSources()"></div><div class="card" id="sourceList">${sourceRows('')}</div>`}
function sourceRows(s){return SOURCES.map((x,i)=>({...x,i})).filter(x=>normal(x.name).includes(normal(s))).map(x=>`<div class="source-row"><h3>${esc(x.name.replace('thuvienhoclieu.com-',''))}</h3><div class="btn-row"><a class="btn secondary" href="${x.file}" download>Tải Word gốc ↓</a><button onclick="sourcePreview(${x.i})">Xem văn bản</button></div><div id="source${x.i}"></div></div>`).join('')||'<p>Không tìm thấy tài liệu.</p>'}
function filterSources(){$('#sourceList').innerHTML=sourceRows($('#sourceSearch').value)}
function sourcePreview(i){let el=$('#source'+i);if(el.textContent){el.innerHTML='';return}el.innerHTML=`<div class="source-text">${esc(SOURCES[i].text)}</div>`}
function settings(){return intro('GIA ĐÌNH CÙNG ĐỒNG HÀNH','Góc phụ huynh','Thiết lập giọng đọc, lịch gợi ý và giữ lại hành trình của con.')+`<div class="columns"><section class="card"><h2>Hồ sơ và lịch học</h2><form id="settingsForm" onsubmit="saveSettings(event)"><label class="field">Tên gọi của con<input id="childName" maxlength="40" value="${esc(state.name)}" required></label><label class="field">Ngày bắt đầu học (không bắt buộc)<input id="startDate" type="date" value="${esc(state.start)}"></label><p class="meta">Lịch tự bỏ thứ Bảy, Chủ nhật; chưa trừ ngày lễ. Có thể chọn bài bất kì trên hành trình.</p><h3>Giọng cô Mi A</h3><p class="meta">Các bài giảng dùng bản đọc giọng nữ Hoài My kèm sẵn. Không cần cài thêm giọng trên Chrome.</p><button type="button" onclick="testRecordedVoice()">▶ Nghe giọng nữ cô Mi A</button><h3 style="margin-top:22px">Giọng đọc hội thoại trên thiết bị</h3><label class="field">Giọng nữ tiếng Việt<select id="voiceSelect" onchange="voiceSelectionChanged()"></select></label><p id="voiceHelp" class="meta" role="status" aria-live="polite"></p><button type="button" id="confirmFemaleVoiceButton" onclick="confirmFemaleVoice()" hidden>Tôi đã nghe và xác nhận đây là giọng nữ</button><label class="field">Tốc độ đọc<select id="rateSelect"><option value="0.8" ${state.rate===.8?'selected':''}>Chậm, rõ · 0,8×</option><option value="0.9" ${state.rate===.9?'selected':''}>Vừa phải · 0,9×</option><option value="1" ${state.rate===1?'selected':''}>Bình thường · 1×</option></select></label><label><input type="checkbox" id="audioOn" ${state.audio?'checked':''}> Cô đọc phản hồi hội thoại</label><div class="btn-row" style="margin-top:22px"><button class="btn" type="submit">Lưu thiết lập</button><button type="button" onclick="testVoice()">▶ Nghe thử giọng đã chọn</button></div></form></section><section><div class="card"><h2>Những điều cần biết</h2><p class="meta">Cô Mi A là nhân vật nữ trẻ, vui vẻ. Đây là gia sư theo kịch bản, có giải thích, ví dụ và hỏi đáp theo bài, chưa phải AI hội thoại tự do.</p><p class="meta">Bài giảng có tệp âm thanh giọng nữ Hoài My đi kèm; giọng tổng hợp này không phải giọng thu của một giáo viên thật. Phần đọc hội thoại dùng Web Speech và không tự dùng giọng nam hoặc giọng chưa xác định. Giọng nữ được nhận diện rõ sẽ được ưu tiên; giọng chưa rõ giới tính chỉ được dùng sau khi phụ huynh nghe thử và xác nhận. Web Speech không cho biết tuổi giọng, nên độ trẻ và tự nhiên vẫn phụ thuộc giọng được cài trên máy. Trên Chrome, nếu chưa có giọng nữ, hãy cài giọng nữ tiếng Việt được hệ điều hành hỗ trợ rồi mở lại trình duyệt, hoặc nghe thử một giọng chưa xác định và xác nhận nếu đúng là nữ.</p><p class="meta">Micro dùng nhận dạng giọng nói của trình duyệt; có thể gửi âm thanh tới dịch vụ của nhà cung cấp, cần Internet và sự cho phép. Phần này dùng tốt hơn trên Chrome/Edge qua localhost hoặc HTTPS. Phụ huynh đồng hành khi bật micro.</p><p class="meta">Bài học, ảnh sách và chấm điểm tự học chạy ngoại tuyến. Nếu đăng nhập học sinh, tiến độ được đồng bộ riêng lên máy chủ. Phòng thi online cần Internet và đăng nhập bằng tên + mã admin cấp.</p><p class="meta">${storageOK?'Trạng thái lưu: đã sẵn sàng.':'Trình duyệt chưa cho lưu bền; hãy xuất tiến độ thường xuyên.'}</p></div><div class="card"><h3>Sao lưu và chuyển máy</h3><div class="btn-row"><button onclick="exportProgress()">↓ Xuất tiến độ JSON</button><label class="btn secondary" style="cursor:pointer">↑ Nhập bản sao<input type="file" id="importFile" accept="application/json,.json" onchange="importProgress(this)" hidden></label></div><p class="meta" style="margin-top:13px">Đổi tên miền hoặc chuyển từ mở file sang GitHub Pages sẽ có vùng lưu khác. Xuất rồi nhập để chuyển tiến độ.</p></div></section></div><div class="card"><h2>Quản trị lớp học MIA</h2><p class="meta">Thêm học sinh, cấp mã riêng, xem kết quả và tạo phòng thi online. Trang này dùng tài khoản và mật khẩu admin riêng. Máy chủ có thể triển khai từ GitHub Actions, không cần Codex.</p><a class="btn" href="admin.html" target="_blank" rel="noopener">Mở trang admin ↗</a></div><div class="card"><h2>Cách dùng trên máy và GitHub</h2><p class="meta">Giải nén toàn bộ thư mục và mở index.html. Để dùng micro, chạy máy chủ cục bộ theo HUONG-DAN.md hoặc đưa các tệp lên GitHub Pages. Không cần nhập khóa API.</p><a href="HUONG-DAN.md" download>Tải hướng dẫn chi tiết ↓</a><p class="meta" style="margin-top:16px">Bản chứa sách và tài liệu người dùng đã cung cấp. Trước khi công khai toàn bộ qua GitHub Pages, cần có quyền phổ biến các tài liệu đó.</p></div>`}
function saveSettings(e){e.preventDefault();let selected=voices.find(v=>v.voiceURI===$('#voiceSelect').value);if(selected&&!TeacherVoice.eligible(selected,state.voiceConfirmedURI)){toast('Hãy nghe thử và xác nhận giọng nữ trước khi lưu, hoặc chọn giọng nữ đã nhận diện.');return}state.name=$('#childName').value.trim()||'Bạn nhỏ';state.start=$('#startDate').value;state.voice=$('#voiceSelect').value;state.rate=Number($('#rateSelect').value);state.audio=$('#audioOn').checked;save();$('#profileName').textContent=state.name+' · Lớp 4';toast('Đã lưu. Cô Mi A sẵn sàng học cùng em!')}
function getVoices(){voices='speechSynthesis'in window?speechSynthesis.getVoices():[];return voices}
function fillVoices(){
 getVoices();let el=$('#voiceSelect');if(!el)return;
 let previous=el.value||state.voice,vi=voices.filter(TeacherVoice.vietnamese),vs=vi.filter(v=>TeacherVoice.gender(v)!=='male');
 el.innerHTML='<option value="">Tự chọn giọng nữ đã nhận diện</option>'+vs.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} · ${TeacherVoice.gender(v)==='female'?'giọng nữ':'chưa xác định — cần nghe thử'} · ${v.localService?'trên máy':'dịch vụ trực tuyến'}</option>`).join('');
 if(vs.some(v=>v.voiceURI===previous))el.value=previous;
 updateVoiceHelp();
}
function voiceSelectionChanged(){previewedVoiceURI='';updateVoiceHelp()}
function updateVoiceHelp(){
 let el=$('#voiceSelect'),help=$('#voiceHelp'),button=$('#confirmFemaleVoiceButton');if(!el||!help||!button)return;
 let selected=voices.find(v=>v.voiceURI===el.value),automatic=TeacherVoice.choose(voices);
 button.hidden=!selected||TeacherVoice.gender(selected)!=='unknown';
 button.disabled=!selected||previewedVoiceURI!==selected.voiceURI;
 if(selected&&TeacherVoice.gender(selected)==='female')help.textContent='Đã nhận diện giọng nữ: '+selected.name+'. Bấm Nghe thử để kiểm tra âm sắc trên máy của bạn.';
 else if(selected&&state.voiceConfirmedURI===selected.voiceURI)help.textContent='Phụ huynh đã nghe và xác nhận giọng này là nữ. Có thể lưu để dùng cho cô Mi A.';
 else if(selected)help.textContent='Trình duyệt không cho biết giới tính giọng này. Bấm Nghe thử, đợi đọc xong rồi chỉ xác nhận nếu bạn nghe đúng là giọng nữ.';
 else if(automatic)help.textContent='Ứng dụng sẽ dùng giọng nữ '+automatic.name+'. Không tự chuyển sang giọng nam nếu giọng này không dùng được.';
 else help.textContent=voices.length?'Chrome/trình duyệt hiện chưa cung cấp giọng nữ tiếng Việt đã nhận diện. Các giọng nam đã được loại khỏi danh sách. Nếu có giọng chưa xác định, hãy nghe thử và xác nhận; nếu không, cần cài giọng nữ phù hợp trên thiết bị.':'Đang chờ trình duyệt nạp danh sách giọng. Có thể bấm Nghe thử để nạp lại.';
}
function confirmFemaleVoice(){
 let v=voices.find(v=>v.voiceURI===$('#voiceSelect')?.value);
 if(!v||TeacherVoice.gender(v)!=='unknown'||previewedVoiceURI!==v.voiceURI){toast('Cần nghe thử hết giọng đang chọn trước khi xác nhận.');return}
 state.voice=v.voiceURI;state.voiceConfirmedURI=v.voiceURI;save();updateVoiceHelp();toast('Đã lưu giọng nữ do phụ huynh xác nhận.')
}
function waitForVoices(){
 if(getVoices().length)return Promise.resolve(voices);
 return new Promise(resolve=>{let until=Date.now()+1500;function poll(){getVoices();if(voices.length||Date.now()>=until){fillVoices();resolve(voices)}else setTimeout(poll,100)}poll()})
}
async function say(text,force=false,override=null,audition=false){
 if(!audition&&typeof MIAReader!=='undefined'){if(!state.audio&&!force)return;stopSpeech();return MIAReader.speak(text)}
 if(!('speechSynthesis'in window)){toast('Trình duyệt này chưa hỗ trợ đọc giọng. Em đọc phần chữ nhé.');return}
 if(!state.audio&&!force)return;
 let request=++speechRequest;pauseTeacherRecording();speechSynthesis.cancel();await waitForVoices();if(request!==speechRequest)return;
 let chosen=override??state.voice;
 let voice=audition&&chosen?voices.find(v=>v.voiceURI===chosen&&TeacherVoice.vietnamese(v)&&TeacherVoice.gender(v)!=='male'):TeacherVoice.choose(voices,chosen,state.voiceConfirmedURI);
 if(!voice){let message='Chưa có giọng nữ tiếng Việt phù hợp. Mở Dành cho phụ huynh để chọn, nghe thử và xác nhận giọng nữ. Ứng dụng sẽ không tự đọc bằng giọng nam.';toast(message);if($('#readStatus'))$('#readStatus').textContent=message;return}
 let chunks=text.match(/[^.!?\n]+[.!?]?/g)||[text];
 chunks.forEach((chunk,index)=>{let u=new SpeechSynthesisUtterance(chunk.trim());u.voice=voice;u.lang='vi-VN';u.rate=override!==null?Number($('#rateSelect')?.value||state.rate):state.rate;
 u.onstart=()=>{if(request===speechRequest&&$('#readStatus'))$('#readStatus').textContent='Cô đang đọc bằng '+voice.name+'…'};
 u.onend=()=>{if(request!==speechRequest||index!==chunks.length-1)return;if($('#readStatus'))$('#readStatus').textContent='Đã đọc xong. Em có thể nghe lại hoặc hỏi cô nhé.';if(audition){previewedVoiceURI=voice.voiceURI;updateVoiceHelp()}};
 u.onerror=()=>{if(request!==speechRequest)return;stopSpeech();let message='Không phát được giọng nữ đã chọn. Hãy kiểm tra giọng và kết nối; ứng dụng không chuyển sang giọng khác.';toast(message);if($('#readStatus'))$('#readStatus').textContent=message};
 speechSynthesis.speak(u)
 })
}
function testVoice(){previewedVoiceURI='';updateVoiceHelp();return say('Chào em, cô là Mi A! Hôm nay mình cùng khám phá Toán lớp bốn nhé. Chưa hiểu thì cứ hỏi cô, mình sẽ thử từng bước một.',true,$('#voiceSelect').value,true)}
function stopSpeech(){if(typeof MIAReader!=='undefined')MIAReader.stop();if(typeof MIAStudio!=='undefined')MIAStudio.stop();speechRequest++;pauseTeacherRecording();if('speechSynthesis'in window)speechSynthesis.cancel();if($('#readStatus'))$('#readStatus').textContent='Đã dừng đọc.'}
function pauseTeacherRecording(){if(teacherAudio){let old=teacherAudio;teacherAudio=null;old.pause();old.removeAttribute('src');old.load()}}
function playTeacherRecording(path,fallback){
 stopSpeech();let request=speechRequest,audio=new Audio(path),failed=false;teacherAudio=audio;
 audio.playbackRate=state.rate/.9;
 audio.onplaying=()=>{if(request===speechRequest&&$('#readStatus'))$('#readStatus').textContent='Cô đang giảng bằng giọng nữ Hoài My…'};
 audio.onended=()=>{if(request!==speechRequest)return;teacherAudio=null;if($('#readStatus'))$('#readStatus').textContent='Cô đã giảng xong. Em thử lại ví dụ rồi xem trang sách nhé!'};
 function fail(){if(failed||request!==speechRequest)return;failed=true;pauseTeacherRecording();if(fallback){toast('Không tải được bản đọc kèm sẵn. Đang kiểm tra giọng nữ trên thiết bị.');say(fallback,true)}else toast('Chưa tải được giọng mẫu. Hãy kiểm tra kết nối hoặc tải lại trang.')}
 audio.onerror=fail;audio.play().catch(error=>{if(error.name!=='AbortError')fail()})
}
function testRecordedVoice(){playTeacherRecording('assets/audio/chao-em.mp3?v=mia1')}
function readShortGuide(){if(window.MIAAccess&&!MIAAccess.require())return;let d=DAYS[currentDay-1],l=LESSONS[d.lesson-1],g=G[l.key];let fallback=`Chào em! Hôm nay cô và em học bài ${l.title}. ${g.rule} ${g.steps.join('. ')} Cùng xem ví dụ. ${g.example}. Nhớ nhé: ${g.mistake}`;playTeacherRecording(`assets/audio/bai-${l.id}.mp3?v=mia1`,fallback)}
function addMessage(text,child=false){messages.push({text,child});if(messages.length>60)messages.shift();renderMessages();if(!child)say(text)}
function renderMessages(){let el=$('#messages');el.innerHTML=messages.map((m,i)=>`<div class="bubble ${m.child?'child':''}">${esc(m.text)}${!m.child?`<br><button class="btn secondary" onclick="say(messages[${i}].text,true)">▶ Nghe lại</button>`:''}</div>`).join('');el.scrollTop=el.scrollHeight}
function toggleChat(open){if(open!==false&&window.MIAAccess&&!MIAAccess.require())return;let el=$('#chat');let show=typeof open==='boolean'?open:el.classList.contains('hidden');el.classList.toggle('hidden',!show);$('#chatLaunch').setAttribute('aria-expanded',String(show));if(show){if(!messages.length)addMessage(`Chào ${state.name}! Cô Mi A đây 🌷. Em có thể hỏi “giảng lại”, “ví dụ”, “gợi ý”, hoặc nhờ “cô hỏi em”. Mình đang xem ngày ${currentDay}.`);$('#chatInput').focus()}}
async function ask(input){if(typeof MIAReader!=='undefined')MIAReader.unlock();if(window.MIAAccess&&!MIAAccess.require())return;toggleChat(true);let text=String(input).trim();if(!text)return;addMessage(text,true);let n=normal(text),l=LESSONS[DAYS[currentDay-1].lesson-1],g=G[l.key];if(chatQuestion&&!/giang|vidu|goiy|bai|hoi|khonghieu|chao|dung/.test(n)){let ok=correct(spokenAnswer(text),chatQuestion.answer);addMessage(ok?'Đúng rồi, em giỏi lắm! '+chatQuestion.why:'Cảm ơn em đã thử! Đáp án là '+chatQuestion.answer+'. '+chatQuestion.why+' Mình đọc lại rồi thử một câu khác nhé.');chatQuestion=null;return}
if(/giang|giaithich|lythuyet|khonghieu|chuahieu|vidu|lammau|visao|taisao|thucte|doisong|cachkhac|chamhon/.test(n)){let day=location.hash.startsWith('#lesson/')?currentDay:MIALearning.context(state,LESSONS,DAYS).day,intent=/cachkhac|chamhon|vanchuahieu/.test(n)?'concrete':/visao|taisao/.test(n)?'why':/thucte|doisong/.test(n)?'real-life':/vidu|lammau/.test(n)?'example':'simpler';let reply=await MIAAdvisor.chat(day,intent);if(reply)addMessage(reply.text+'\n\n'+MIALessonCoach.lines.comfort);return}
if(/dung|imlang/.test(n)){stopSpeech();addMessage('Cô đã dừng. Khi muốn học tiếp, em nhắn cô nhé.');stopSpeech();return}
if(/giang|lythuyet|khonghieu|chuahieu/.test(n))addMessage('Mình cùng đi chậm lại nhé! '+g.rule+'\n'+g.steps.map((s,i)=>(i+1)+'. '+s).join('\n'));
else if(/vidu|lammau/.test(n))addMessage('Cô làm mẫu nhé:\n'+g.example+'\nEm thử kể lại bước đầu tiên bằng lời của mình.');
else if(/goiy|sai|nham/.test(n))addMessage('Cô nhắc em một mẹo nhé: '+g.mistake+'\nHãy đọc lại yêu cầu, xác định điều đã biết rồi chọn bước đầu tiên.');
else if(/hoi|caukhac|kiemtra|luyentap/.test(n)){chatQuestion=question(l.key,Math.floor(Math.random()*1000));addMessage('Cô hỏi một câu nhé: '+chatQuestion.q+(chatQuestion.options?'\nEm chọn: '+chatQuestion.options.join(' / '):'')+'\nEm gõ hoặc nói đáp án. Nếu là phân số, gõ dạng 2/3 nhé.')}
else if(/chao|camon/.test(n))addMessage('Cô rất vui được học cùng em! Hôm nay mình đang học “'+l.title+'”. Em muốn cô giảng lại, làm mẫu hay hỏi một câu?');
else addMessage('Cô đang hỗ trợ theo nội dung bài “'+l.title+'”. Em chọn “Giảng lại”, “Ví dụ”, “Gợi ý” hoặc “Cô hỏi em” để mình tiếp tục nhé. Câu hỏi mở cần suy luận thêm, em nhờ phụ huynh hoặc thầy cô cùng trao đổi.');}
$('#chatForm').onsubmit=e=>{e.preventDefault();let text=$('#chatInput').value;$('#chatInput').value='';ask(text)};
function listen(){if(window.MIAAccess&&!MIAAccess.require())return;let Rec=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Rec){toast('Micro chưa được hỗ trợ. Hãy dùng Chrome/Edge hoặc gõ câu hỏi.');return}if(!window.isSecureContext){toast('Micro cần HTTPS hoặc localhost. Em có thể gõ khi mở file trực tiếp.');return}if(!sessionStorage.getItem('vuontoan-mic-consent')){if(!confirm('Bật nhận dạng giọng nói? Trình duyệt có thể gửi âm thanh đến dịch vụ nhận dạng của nhà cung cấp. Phụ huynh đồng ý cho con sử dụng?'))return;sessionStorage.setItem('vuontoan-mic-consent','yes')}stopSpeech();if(recognition){recognition.abort();recognition=null}recognition=new Rec();recognition.lang='vi-VN';recognition.interimResults=false;recognition.onresult=e=>{let text=e.results[0][0].transcript;$('#chatInput').value=text;ask(text);$('#chatInput').value=''};recognition.onerror=e=>toast(e.error==='not-allowed'?'Micro chưa được cho phép. Em có thể gõ câu trả lời.':'Chưa nghe được. Kiểm tra micro, Internet hoặc gõ câu trả lời.');recognition.onend=()=>recognition=null;try{recognition.start();toast('Cô đang nghe… Em nói ngắn gọn nhé!')}catch(e){toast('Chưa bật được micro. Em gõ câu trả lời nhé.')}}
function download(name,text,type){let blob=new Blob(['\ufeff'+text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function exportProgress(){download('vuon-toan-4-tien-do.json',JSON.stringify({format:'vuontoan4',version:1,state},null,2),'application/json')}
function exportCSV(){let rows=[['Ngày làm','Loại','Từ ngày','Đến ngày','Điểm / 10','Đúng','Tổng câu'],...state.results.map(r=>[new Date(r.date).toLocaleDateString('vi-VN'),KINDS[r.kind],r.start,r.end,r.score,r.good,r.total])];download('vuon-toan-4-bang-diem.csv',rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8')}
async function importProgress(input){let f=input.files[0];if(!f)return;try{if(f.size>15000000)throw Error();let data=JSON.parse((await f.text()).replace(/^\uFEFF/,'')),s=data.state;if(data.format!=='vuontoan4'||data.version!==1||!s||typeof s.name!=='string'||s.name.length>40||!Array.isArray(s.completed)||!Array.isArray(s.read)||!Array.isArray(s.results))throw Error();for(let ids of [s.completed,s.read])if(ids.some(x=>!Number.isInteger(x)||x<1||x>175))throw Error();for(let r of s.results){if(!KINDS[r.kind]||!Number.isFinite(r.score)||r.score<0||r.score>10||!Number.isInteger(r.start)||!Number.isInteger(r.end)||r.start<1||r.end>175||r.start>r.end||!Array.isArray(r.questions)||r.questions.length>30)throw Error();for(let q of r.questions)if(['q','answer','why','source','key'].some(k=>typeof q[k]!=='string')||(q.options!==null&&!Array.isArray(q.options)))throw Error()}if(!confirm('Nhập bản sao sẽ thay thế tiến độ hiện tại. Bạn đã xuất bản sao hiện tại nếu cần?'))return;state={name:s.name,start:/^\d{4}-\d{2}-\d{2}$/.test(s.start)?s.start:'',voice:typeof s.voice==='string'?s.voice:'',voiceConfirmedURI:typeof s.voiceConfirmedURI==='string'?s.voiceConfirmedURI:'',rate:[.8,.9,1].includes(s.rate)?s.rate:.9,audio:!!s.audio,completed:[...new Set(s.completed)],read:[...new Set(s.read)],results:s.results,learning:MIALearning.clean(s.learning)};save();route();toast('Đã khôi phục tiến độ.')}catch(e){toast('Tệp không đúng định dạng tiến độ Học Toán cùng MIA. Dữ liệu hiện tại vẫn được giữ.')}input.value=''}
if('speechSynthesis'in window)speechSynthesis.onvoiceschanged=fillVoices;
window.addEventListener('hashchange',route);route();

// Hỗ trợ câu trả lời ngắn được nhận dạng thành chữ tiếng Việt.
function spokenAnswer(text){
 if(numeric(text)!==null)return text;
 let plain=String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/[.!?,]/g,'').trim();
 if(plain.includes(' phan ')){let parts=plain.split(' phan ');if(parts.length===2){let a=spokenNumber(parts[0]),b=spokenNumber(parts[1]);if(a!==null&&b!==null&&b!==0)return a+'/'+b}}
 let n=spokenNumber(plain);return n===null?text:n;
}
function spokenNumber(text){let words=text.trim().split(/\s+/),map={khong:0,mot:1,hai:2,ba:3,bon:4,tu:4,nam:5,lam:5,sau:6,bay:7,tam:8,chin:9},total=0,group=0,digit=0,has=false;
 for(let w of words){if(w in map){digit=map[w];has=true}else if(/^\d+$/.test(w)){digit=Number(w);has=true}else if(w==='muoi'){group+=(digit||1)*10;digit=0;has=true}else if(w==='tram'){group+=digit*100;digit=0}else if(['nghin','ngan','trieu','ty'].includes(w)){let scale=w==='trieu'?1000000:w==='ty'?1000000000:1000;total+=(group+digit)*scale;group=0;digit=0}else if(!['linh','le'].includes(w))return null}
 return has?total+group+digit:null;
}

if(typeof MIAOnline!=='undefined')MIAOnline.init();

function learningRecord(kind,day,extra={}){if(window.MIAAccess&&!MIAAccess.require())return;let at=Date.now(),id=kind==='practice'?'practice:'+at:kind+':'+MIALearning.today()+':'+day;if(MIALearning.record(state,{id,kind,day,at,...extra})){save();return true}return false}
function checkinCard(plan){let last=plan.current||plan.previous;return `<section class="card mia-checkin ${plan.current?'checked-in':''}"><div><span class="eyebrow">CÔ MUỐN HIỂU EM HƠN</span><h2>Hôm nay trên lớp con đã học đến đâu rồi?</h2><p>${plan.current?'Cô đã nhớ bài hôm nay. Nếu chọn nhầm, em có thể đổi lại.':last?'Lần trước em chọn bài '+last.lesson+'. Hôm nay lớp mình vẫn học bài này hay đã sang bài khác?':'Chọn bài hoặc gõ tên bài, số trang trong sách. Cô sẽ sắp xếp việc hôm nay cho vừa sức em.'}</p>${plan.current?'<button class="mia-change-school" type="button" onclick="this.closest(\'.mia-checkin\').classList.toggle(\'expanded\')">Đổi bài / trang đang học</button>':''}</div><form id="schoolCheckin" onsubmit="saveSchoolCheckin(event)"><label>Tìm bài trong sách<input type="search" id="schoolSearch" oninput="filterSchoolLessons()" placeholder="Ví dụ: phân số, bài 20, trang 43" autocomplete="off"></label><div id="schoolSuggestions" class="mia-school-suggestions">${[...new Set([last?.lesson||plan.lesson,Math.min(73,(last?.lesson||plan.lesson)+1)])].map(id=>schoolSuggestion(LESSONS[id-1])).join('')}</div><div class="mia-school-filters"><label>Tập sách<select id="schoolBook" onchange="filterSchoolLessons()"><option value="all">Cả hai tập</option><option value="1">Tập 1</option><option value="2">Tập 2</option></select></label><label>Bài đang học<select id="schoolLesson" onchange="loadSchoolSessions()" required>${schoolOptions('', 'all',last?.lesson||null)}</select></label></div><label>Trang / buổi đang học<select id="schoolSession" required>${last?schoolSessions(last.lesson,last.day||plan.day):'<option value="">Con chọn bài ở trên trước nhé</option>'}</select></label><fieldset class="mia-feelings"><legend>Với bài này, con thấy thế nào?</legend>${[['unsure','🌱','Con còn chưa hiểu'],['okay','🌤','Con hiểu một phần'],['confident','🌟','Con khá tự tin']].map(([value,icon,label])=>`<label><input type="radio" name="feeling" value="${value}" required ${value===(last?.feeling||'')?'checked':''}><span>${icon} ${label}</span></label>`).join('')}</fieldset><div class="btn-row"><button class="btn" type="submit">${plan.current?'Cập nhật bài của con':'Cô lên kế hoạch cho con nhé'} →</button><small id="checkinStatus" role="status">Chọn bài là xác nhận tiến độ trên lớp, chưa phải kết quả kiểm tra.</small></div></form></section>`}
function schoolOptions(search,book,selected){let query=normal(search).replace(/^bai\s+/,''),matches=LESSONS.filter(l=>(book==='all'||String(l.book)===book)&&(!query||normal(l.title+' '+l.id+' trang '+l.page+' '+l.end).includes(query)||(/^\d+$/.test(query)&&Number(query)>=l.page&&Number(query)<=l.end)));return matches.length?(!matches.some(l=>l.id===selected)?'<option value="">Con chọn bài đang học trên lớp…</option>':'')+matches.map(l=>`<option value="${l.id}" ${l.id===selected?'selected':''}>Bài ${l.id} · ${esc(l.title)} · Tập ${l.book}, tr. ${l.page}–${l.end}</option>`).join(''):'<option value="">Chưa tìm thấy bài; thử tên bài hoặc đổi tập sách</option>'}
function filterSchoolLessons(){let selected=Number($('#schoolLesson').value);$('#schoolLesson').innerHTML=schoolOptions($('#schoolSearch').value,$('#schoolBook').value,selected);loadSchoolSessions();let ids=[...$('#schoolLesson').options].map(o=>Number(o.value)).filter(id=>LESSONS[id-1]).slice(0,6);$('#schoolSuggestions').innerHTML=ids.map(id=>schoolSuggestion(LESSONS[id-1])).join('')}
function schoolSuggestion(l){return `<button type="button" onclick="chooseSchoolLesson(${l.id})"><b>Bài ${l.id} · ${esc(l.title)}</b><small>Tập ${l.book} · Trang ${l.page}–${l.end}</small></button>`}
function chooseSchoolLesson(id){$('#schoolLesson').value=String(id);loadSchoolSessions();$('#schoolSession').focus()}
function schoolSessions(lesson,day){return DAYS.filter(d=>d.lesson===Number(lesson)).map(d=>`<option value="${d.id}" ${d.id===day?'selected':''}>Buổi ${d.session}/${d.total} · Trang ${d.start}–${d.end}</option>`).join('')}
function loadSchoolSessions(){$('#schoolSession').innerHTML=schoolSessions(Number($('#schoolLesson').value),null)}
function saveSchoolCheckin(event){if(window.MIAAccess&&!MIAAccess.require())return;event.preventDefault();let lesson=Number($('#schoolLesson').value),feeling=new FormData(event.target).get('feeling');if(!LESSONS[lesson-1]||!['unsure','okay','confident'].includes(feeling))return;MIALearning.checkin(state,lesson,feeling,Date.now(),Number($('#schoolSession').value));save();route();$('#todayPlan')?.scrollIntoView({behavior:'smooth',block:'start'});toast('Cô đã nhớ bài '+lesson+'. Mình làm từng việc nhỏ nhé!')}
function dailyPlanCard(plan){let ready=!!plan.current;return `<section class="card mia-today-plan" id="todayPlan"><div class="section-head"><div><span class="eyebrow">${ready?'VIỆC HÔM NAY CỦA EM':'GỢI Ý TẠM THỜI · CHỌN BÀI Ở TRÊN ĐỂ ĐIỀU CHỈNH'}</span><h2>${ready?'Mình học vừa sức, hiểu thật chắc':'Cô chờ con chọn bài đang học nhé'}</h2></div><span class="tag">${plan.done}/${plan.tasks.length} việc · còn khoảng ${plan.minutes} phút</span></div><p>Bài ${plan.lesson}: <b>${esc(LESSONS[plan.lesson-1].title)}</b>${plan.current?.feeling==='unsure'?' · Hôm nay mình ưu tiên nghe chậm và luyện lại.':''}</p><div class="mia-plan-list">${plan.tasks.map((task,i)=>`<a class="mia-plan-task ${task.done?'done':''}" href="${task.href}"><span class="mia-plan-number">${task.done?'✓':i+1}</span><div><b>${esc(task.title)}</b><small>${esc(task.why)}</small></div><span class="mia-plan-time">${task.done?'Đã làm':task.minutes+' phút →'}</span></a>`).join('')}</div><p class="meta" style="margin-top:14px">Sau khi làm bài, cô cập nhật gợi ý theo từng câu. Nếu mỏi, em nghỉ một chút rồi học tiếp; không cần chạy đua để đánh dấu đủ việc.</p></section>`}
function topicLesson(key){return LESSONS.find(l=>l.key===key)||LESSONS.find(l=>GROUPS[l.key]?.includes(key))}
function knowledgeCard(){let topics=MIALearning.topics(state,correct),context=MIALearning.context(state,LESSONS,DAYS);return `<section class="card mia-knowledge"><span class="eyebrow">CÔ THEO DÕI CÁCH EM HIỂU BÀI</span><h2>Kiến thức nào mình cần chăm thêm?</h2><p>${context.previous?'Bài trên lớp gần nhất: '+esc(LESSONS[context.previous.lesson-1].title)+'. ':''}Đánh giá dưới đây dựa vào câu đã chấm, không dựa vào việc bấm “đã đọc”.</p>${topics.length?`<div class="mia-knowledge-grid">${topics.sort((a,b)=>a.rate-b.rate).slice(0,12).map(t=>{let l=topicLesson(t.key),day=l?DAYS.find(d=>d.lesson===l.id).id:1;return `<article class="mia-topic ${t.level}"><span class="tag">${({new:'Cần thêm dữ liệu',review:'Nên luyện lại',growing:'Đang tiến bộ',steady:'Làm khá chắc'})[t.level]}</span><h3>${esc(l?.title||t.key)}</h3><p>Đúng ${t.good}/${t.n} câu gần nhất · ${Math.round(t.rate*100)}%</p><a href="#lesson/${day}/practice">${t.level==='review'?'Cô cùng em gỡ lỗi':'Ôn một chút để nhớ lâu'} →</a></article>`}).join('')}</div>`:'<div class="note">Cô chưa có đủ kết quả để nhận xét. Em chọn bài trên lớp và làm ba câu luyện tập; cô sẽ bắt đầu từ kết quả đó.</div>'}<p class="meta" style="margin-top:15px">Mỗi chủ đề xem tối đa 12 câu gần nhất. Một vài câu chưa nói lên toàn bộ khả năng của em; cô cần nhiều lần thực hành để gợi ý tốt hơn.</p></section>`}
function studioProgram(l,d){if(typeof MIA_STUDIO_AUDIO==='undefined')return[];let rows=MIALessons.keys(l,d).flatMap(key=>{let audio=MIA_STUDIO_AUDIO.topics[key];if(!audio)return[];return MIALessons.parts(key).map((p,i)=>({...p,key,file:'assets/audio/studio/'+audio.file,...audio.spans[i]}))});return[MIALessonCoach.segment('intro'),...rows,MIALessonCoach.segment('comfort')].filter(Boolean)}
function studioMarkup(l,d){return `<section class="card mia-studio"><div class="section-head"><div><span class="eyebrow">LỚP HỌC TỪNG BƯỚC CÙNG MIA</span><h2>Nghe cô giảng, nhìn cô viết</h2></div><span class="tag">Có thể dừng và nghe lại</span></div><p>Cô đọc chậm hơn và nghỉ 3–4 giây giữa các bước, 6 giây sau câu mời con thử để con kịp suy nghĩ. Con có thể bấm tạm dừng lâu hơn. Bảng viết theo bước đang đọc; sách giáo khoa gốc vẫn ở mục bên cạnh.</p><div class="mia-studio-layout"><div class="mia-writing-board"><div class="mia-writing-top"><span id="studioTitle">Cô Mi A đang chờ em</span><span id="studioCount">Chuẩn bị vở nháp nhé</span></div><div id="studioPrevious" class="mia-writing-previous"></div><div id="studioDiagram" class="mia-studio-diagram"></div><div id="studioWriting" class="mia-writing-current" aria-live="off">Bấm “Cô giảng từng bước”. Em có thể nghe chậm, tạm dừng hoặc xem lại đúng bước chưa hiểu.</div><div class="mia-chalk-pencil" aria-hidden="true">✎</div></div><div class="mia-studio-teacher">${teacher}<p id="studioStatus" role="status">Giọng nữ Hoài My · Có hai ví dụ và lời giải từng bước.</p><label>Tốc độ cô giảng<select id="studioRate" onchange="MIAStudio.rate(Number(this.value))"><option value="0.75">Rất chậm · 0,75×</option><option value="0.85" selected>Chậm, rõ · 0,85×</option><option value="1">Vừa phải · 1×</option><option value="1.1">Nhanh hơn · 1,1×</option></select></label></div></div><div class="mia-studio-controls"><button class="btn" onclick="readGuide()">▶ Cô giảng từng bước</button><button onclick="MIAStudio.pause()">Ⅱ Tạm dừng</button><button onclick="MIAStudio.jump(-1)">← Bước trước</button><button onclick="MIAStudio.jump(1)">Bước tiếp →</button></div><div class="btn-row" style="margin-top:18px"><button class="btn secondary" onclick="markRead();setTab('book')">Em đã đọc và hiểu, xem sách →</button><button onclick="toggleChat(true);ask('Cô giảng lại nhé')">Em vẫn chưa hiểu</button></div><small class="meta">Nút “đã đọc và hiểu” là tự nhận xét; cô chỉ đánh giá mức nắm bài qua câu em làm.</small></section>`}
let studioDay=null;
function readGuide(){if(window.MIAAccess&&!MIAAccess.require())return;if(studioDay===currentDay&&$('#studioWriting')?.dataset.configured==='yes'){MIAStudio.start();return}stopSpeech();if(typeof ExamTeacher!=='undefined')ExamTeacher.stop();let d=DAYS[currentDay-1],l=LESSONS[d.lesson-1],program=studioProgram(l,d);if(!program.length){toast('Chưa tải được bài giảng từng bước. Em có thể nghe bản tóm tắt và đọc ví dụ ở dưới.');return}studioDay=currentDay;let mark=$('#studioWriting');if(mark)mark.dataset.configured='yes';let day=currentDay;MIAStudio.configure(program,{write({row,index,total,progress}){if(currentDay!==day||!$('#studioWriting'))return;$('#studioDiagram').innerHTML=studioDiagram(row);$('#studioTitle').textContent=row.title;$('#studioCount').textContent='Bước '+(index+1)+' / '+total;let amount=Math.max(0,Math.min(1,(progress-.08)/.68));$('#studioWriting').textContent=row.board.slice(0,Math.max(1,Math.ceil(row.board.length*amount)));$('#studioWriting').scrollTop=$('#studioWriting').scrollHeight;$('#studioPrevious').textContent=program.slice(Math.max(0,index-2),index).map(p=>p.board).join('\n');},state(value,detail){let el=$('#studioStatus');if(el)el.textContent=({thinking:'Con nhìn lại dòng trên bảng và suy nghĩ nhé. Cô đọc tiếp sau '+(detail?.seconds||0)+' giây.',playing:'Cô đang giảng chậm; bảng viết theo đúng bước đang đọc.',paused:'Đã tạm dừng cả giọng đọc và bảng viết.',stopped:'Đã dừng. Bấm bắt đầu để nghe lại.',finished:'Cô đã giảng xong. Mình xem sách giáo khoa, cùng luyện tập rồi kiểm tra ngày nhé.',blocked:'Bấm “Cô giảng từng bước” để cho phép phát âm thanh.',error:'Chưa tải được âm thanh. Em có thể xem từng bước hoặc thử lại.'})[value]||''},complete(){learningRecord('lecture-complete',day);toast('Con nghe xong rồi. Mình xem sách, luyện tập và kiểm tra ngày nhé!')}});MIAStudio.start()}

function studioDiagram(row){let match=row.board.match(/(\d+)\s*\/\s*(\d+)/);if(!match)return '';let n=Number(match[1]),d=Number(match[2]);if(d<2||d>12||n<0||n>d)return '';return `<div class="mia-fraction-bar" style="grid-template-columns:repeat(${d},1fr)">${Array.from({length:d},(_,i)=>`<span class="${i<n?'filled':''}"></span>`).join('')}</div><small>Minh họa ${n}/${d}: lấy ${n} trong ${d} phần bằng nhau.</small>`}
